static void hex(const unsigned char *d, size_t n, char *out) {
    static const char *H = "0123456789abcdef";
    for (size_t i = 0; i < n; i++) { out[i*2] = H[d[i] >> 4]; out[i*2+1] = H[d[i] & 15]; }
    out[n*2] = '\0';
}

int main(void) {
    printf("=== wubu_aead (slerm gate, SLERM-2022) ===\n");
    unsigned char got[64];
    char a[129], b[129];

    for (size_t i = 0; i < sizeof POLY / sizeof POLY[0]; i++) {
        const PolyVec *v = &POLY[i];
        wubu_poly1305(got, v->msg, v->mlen, v->key);
        hex(got, 16, a); hex(v->tag, 16, b);
        if (!strcmp(a, b)) pass++;
        else { printf("  [FAIL] poly1305 %-10s got %s want %s\n", v->name, a, b); fail++; }
    }

    for (size_t i = 0; i < sizeof AEAD / sizeof AEAD[0]; i++) {
        const AeadVec *v = &AEAD[i];
        unsigned char ct[1024], tag[16], pt[1024];
        int rc = wubu_aead_seal(ct, tag, v->pt, v->ptlen, v->aad, v->aadlen, v->key, v->nonce);
        hex(tag, 16, a); hex(v->tag, 16, b);
        if (rc == 0 && !memcmp(ct, v->ct, v->ctlen) && !strcmp(a, b)) pass++;
        else { printf("  [FAIL] seal %-14s rc=%d tag %s want %s\n", v->name, rc, a, b); fail++; }

        memset(pt, 0xAA, sizeof pt);
        rc = wubu_aead_open(pt, sizeof pt, v->ct, v->ctlen, v->tag, v->aad, v->aadlen, v->key, v->nonce);
        if (rc == 0 && !memcmp(pt, v->pt, v->ptlen)) pass++;
        else { printf("  [FAIL] open %-14s rc=%d\n", v->name, rc); fail++; }

        /* a flipped ciphertext byte must be refused AND must not write plaintext */
        if (v->ctlen) {
            unsigned char bad[1024];
            memcpy(bad, v->ct, v->ctlen);
            bad[v->ctlen / 2] ^= 0x01;
            memset(pt, 0xAA, sizeof pt);
            rc = wubu_aead_open(pt, sizeof pt, bad, v->ctlen, v->tag, v->aad, v->aadlen, v->key, v->nonce);
            int untouched = 1;
            for (size_t k = 0; k < v->ptlen; k++) if (pt[k] != 0xAA) untouched = 0;
            if (rc == WUBU_AEAD_TAG_BAD && untouched) pass++;
            else { printf("  [FAIL] %-14s tampered ciphertext rc=%d untouched=%d\n", v->name, rc, untouched); fail++; }
        }

        /* a flipped tag, a flipped AAD byte and the wrong nonce are all refusals */
        unsigned char t2[16];
        memcpy(t2, v->tag, 16); t2[0] ^= 1;
        if (wubu_aead_open(pt, sizeof pt, v->ct, v->ctlen, t2, v->aad, v->aadlen, v->key, v->nonce) == WUBU_AEAD_TAG_BAD) pass++;
        else { printf("  [FAIL] %-14s bad tag accepted\n", v->name); fail++; }
        if (v->aadlen) {
            unsigned char aad2[128];
            memcpy(aad2, v->aad, v->aadlen); aad2[0] ^= 1;
            if (wubu_aead_open(pt, sizeof pt, v->ct, v->ctlen, v->tag, aad2, v->aadlen, v->key, v->nonce) == WUBU_AEAD_TAG_BAD) pass++;
            else { printf("  [FAIL] %-14s bad AAD accepted\n", v->name); fail++; }
        }
        {
            unsigned char n2[12];
            memcpy(n2, v->nonce, 12); n2[11] ^= 0x80;
            if (wubu_aead_open(pt, sizeof pt, v->ct, v->ctlen, v->tag, v->aad, v->aadlen, v->key, n2) == WUBU_AEAD_TAG_BAD) pass++;
            else { printf("  [FAIL] %-14s wrong nonce accepted\n", v->name); fail++; }
        }
        /* an undersized plaintext buffer is refused before any work */
        if (v->ctlen && wubu_aead_open(pt, v->ctlen - 1, v->ct, v->ctlen, v->tag, v->aad, v->aadlen, v->key, v->nonce) == WUBU_AEAD_SMALL) pass++;
        else if (v->ctlen) { printf("  [FAIL] %-14s small buffer accepted\n", v->name); fail++; }
    }

    /* null arguments never crash */
    if (wubu_aead_seal(NULL, NULL, NULL, 0, NULL, 0, NULL, NULL) == WUBU_AEAD_ARGS) pass++;
    else { printf("  [FAIL] null seal accepted\n"); fail++; }

    printf("\n=== %d passed, %d failed ===\n", pass, fail);
    return fail ? 1 : 0;
}
